const oldStorage=globalThis.localStorage,oldLocation=globalThis.location,personalStore=new Map();globalThis.localStorage={getItem:k=>personalStore.get(k)||null,setItem:(k,v)=>personalStore.set(k,String(v))};globalThis.location={search:'?starter-axe=1'};qa.rawStart();assert.equal(gameDiagnostics().hasAxe,true);assert.equal(qa.axePickup.visible,false);assert.equal(element('objective').textContent,'שבור את דלת היציאה');qa.setPlayer({x:0,z:12});qa.interact();assert.equal(gameDiagnostics().hits,1,'Starting axe can actually break exit boards');qa.menu();globalThis.location.search='';qa.rawStart();assert.equal(gameDiagnostics().hasAxe,true,'Preference survives a new run without activation link');assert.equal(gameDiagnostics().hits,0,'New run resets door damage');globalThis.localStorage={getItem:()=>null,setItem(){}};qa.rawStart();assert.equal(gameDiagnostics().hasAxe,false,'A different browser starts with normal hidden axe');assert.equal(qa.axePickup.visible,true);globalThis.localStorage={getItem:k=>personalStore.get(k)||null,setItem:(k,v)=>personalStore.set(k,String(v))};globalThis.location.search='?starter-axe=0';qa.rawStart();assert.equal(gameDiagnostics().hasAxe,false,'Personal option can be switched off');globalThis.localStorage=oldStorage;globalThis.location=oldLocation;console.log('Personal axe: activation, functional exit, persistence, reset and other-player defaults passed');
